contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll test with sellCreditMarket which transfers borrowAToken from lender to caller and feeRecipient.
    // We cannot mint tokens here; we only assert an invariant about balances around a successful call.
    // Parameters: lender (the msg.sender in c will be this contract for subsequent internal transfers), creditPositionId,
    // amount, tenor, deadline, maxAPR, exactAmountIn. We will only call sellCreditMarket and observe that when it does not revert,
    // the sum of borrowAToken transfers from lender equals cashAmountOut + fees as reflected by borrowAToken balances of participants.

    function run(address lender, uint256 creditPositionId, uint256 amount, uint256 tenor, uint256 deadline, uint256 maxAPR, bool exactAmountIn) public payable {
        require(true);

        // Observe balances before
        address borrowATokenAddr = address(c.data().borrowAToken);
        // Use public view calls on c to get borrowAToken object through data().borrowAToken is NonTransferrableScaledToken; we only can call its public functions via the interface through the address.
        // However, we can only observe via SizeView: getUserView, data(), borrowAToken.balanceOf(account) is available because borrowAToken is a public contract with balanceOf.
        uint256 balLenderBefore = c.getUserView(lender).borrowATokenBalance;
        uint256 balCallerBefore = c.getUserView(address(this)).borrowATokenBalance;
        InitializeFeeConfigParams memory fBefore = c.feeConfig();

        bool reverted;
        // Perform the sellCreditMarket call as this contract (msg.sender == this). We must catch revert.
        try c.sellCreditMarket(SellCreditMarketParams({
            lender: lender,
            creditPositionId: creditPositionId,
            amount: amount,
            tenor: tenor,
            deadline: deadline,
            maxAPR: maxAPR,
            exactAmountIn: exactAmountIn
        })) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe balances after
        uint256 balLenderAfter = c.getUserView(lender).borrowATokenBalance;
        uint256 balCallerAfter = c.getUserView(address(this)).borrowATokenBalance;
        InitializeFeeConfigParams memory fAfter = c.feeConfig();

        // If call reverted, we assert nothing about balances (but must still have a general rule). We assert: if the call reverted, balances unchanged.
        // If call succeeded, then the lender's borrowAToken decrease equals caller increase + feeRecipient increase (but we cannot read feeRecipient balance directly via getUserView unless feeRecipient is an EOA; we can instead assert conservation: lender decrease >= caller increase)

        // Build condition: either reverted and balances unchanged, or succeeded and lender decrease >= caller increase and feeRecipient unchanged check skipped; also protocol's feeRecipient must be non-zero in config.
        if (reverted) {
            assert(balLenderAfter == balLenderBefore && balCallerAfter == balCallerBefore && fBefore.feeRecipient == fAfter.feeRecipient);
        } else {
            uint256 lenderDec = balLenderBefore >= balLenderAfter ? balLenderBefore - balLenderAfter : 0;
            uint256 callerInc = balCallerAfter >= balCallerBefore ? balCallerAfter - balCallerBefore : 0;
            // General rule: lender decrease is at least caller increase (fees taken from lender), and protocol feeRecipient remains unchanged in config
            assert(lenderDec >= callerInc && fBefore.feeRecipient == fAfter.feeRecipient);
        }
    }

    // Define the structs used in the call (must match C's interface). We re-declare only param struct types locally to compile call.
    struct SellCreditMarketParams {
        address lender;
        uint256 creditPositionId;
        uint256 amount;
        uint256 tenor;
        uint256 deadline;
        uint256 maxAPR;
        bool exactAmountIn;
    }

    // Re-declare InitializeFeeConfigParams for reading feeRecipient via c.feeConfig()
    struct InitializeFeeConfigParams { uint256 swapFeeAPR; uint256 fragmentationFee; uint256 liquidationRewardPercent; uint256 overdueCollateralProtocolPercent; uint256 collateralProtocolPercent; address feeRecipient; }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We declare only the minimal param struct for the external call; its layout must match the one in C's interface.
    struct SellCreditMarketParamsLocal {
        address lender;
        uint256 creditPositionId;
        uint256 amount;
        uint256 tenor;
        uint256 deadline;
        uint256 maxAPR;
        bool exactAmountIn;
    }

    // Single public function performing the property-based check.
    function run(address lender, uint256 creditPositionId, uint256 amount, uint256 tenor, uint256 deadline, uint256 maxAPR, bool exactAmountIn) public payable {
        // no precondition on parameters
        require(true);

        // Observe borrow aToken balances via SizeView.getUserView for lender and this contract before the call.
        // getUserView returns UserView with borrowATokenBalance field.
        (,,) = (address(0), uint256(0), bool(false)); // no-op to satisfy some static analyzers
        uint256 balLenderBefore = c.getUserView(lender).borrowATokenBalance;
        uint256 balCallerBefore = c.getUserView(address(this)).borrowATokenBalance;

        bool reverted;
        // Prepare local struct to pass to external function by encoding the calldata
        SellCreditMarketParamsLocal memory p = SellCreditMarketParamsLocal({
            lender: lender,
            creditPositionId: creditPositionId,
            amount: amount,
            tenor: tenor,
            deadline: deadline,
            maxAPR: maxAPR,
            exactAmountIn: exactAmountIn
        });

        // Call sellCreditMarket and capture revert without nesting the state-changing call inside a try that would violate constraints.
        // But the prompt allows try/catch. We call via low-level call to match signature to avoid redeclaring the external struct type mismatch.
        // Build calldata for c.sellCreditMarket((...)) selector.
        bytes memory data = abi.encodeWithSignature(
            "sellCreditMarket((address,uint256,uint256,uint256,uint256,uint256,bool))",
            // pack as the single tuple argument matching SellCreditMarketParams
            abi.encode(p.lender, p.creditPositionId, p.amount, p.tenor, p.deadline, p.maxAPR, p.exactAmountIn)
        );

        // Perform the call and catch revert
        (bool ok, ) = address(c).call{value: 0}(data);
        reverted = !ok;

        // Observe balances after
        uint256 balLenderAfter = c.getUserView(lender).borrowATokenBalance;
        uint256 balCallerAfter = c.getUserView(address(this)).borrowATokenBalance;

        // Assert the invariant: either call reverted and balances unchanged, or call succeeded and lender decrease >= caller increase
        if (reverted) {
            assert(balLenderAfter == balLenderBefore && balCallerAfter == balCallerBefore);
        } else {
            uint256 lenderDec = balLenderBefore >= balLenderAfter ? balLenderBefore - balLenderAfter : 0;
            uint256 callerInc = balCallerAfter >= balCallerBefore ? balCallerAfter - balCallerBefore : 0;
            assert(lenderDec >= callerInc);
        }
    }

    // allow receiving ETH if needed
    receive() external payable {}
}

