    // We take parameters that can drive buyCreditMarket: borrower, creditPositionId, amount, tenor, deadline, minAPR, exactAmountIn
    function run(address borrower, uint256 creditPositionId, uint256 amount, uint256 tenor, uint256 deadline, uint256 minAPR, bool exactAmountIn) public payable {
        require(address(this).balance >= 0);
        // Observe supplies before
        uint256 beforeBorrowSupply = c.data().borrowAToken.totalSupply();
        uint256 beforeDebtSupply = c.data().debtToken.totalSupply();

        bool reverted = false;
        // Prepare params struct for buyCreditMarket
        // We must ABI-encode the BuyCreditMarketParams and call c.buyCreditMarket
        // Build calldata according to function signature: buyCreditMarket((address,uint256,uint256,uint256,uint256,uint256,bool))
        bytes memory callData = abi.encodeWithSelector(
            c.buyCreditMarket.selector,
            // struct fields in order: borrower, creditPositionId, amount, tenor, deadline, minAPR, exactAmountIn
            borrower,
            creditPositionId,
            amount,
            tenor,
            deadline,
            minAPR,
            exactAmountIn
        );

        // Try the call and catch revert
        (bool ok, ) = address(c).call{value: 0}(callData);
        if (!ok) reverted = true;

        // Observe supplies after
        uint256 afterBorrowSupply = c.data().borrowAToken.totalSupply();
        uint256 afterDebtSupply = c.data().debtToken.totalSupply();

        // Rule: If the call succeeded (not reverted) then borrowAToken supply never decreases.
        // And if not in multicall, any increase of borrowAToken supply is at most the decrease in debt token supply plus the increase (i.e. borrow increase <= debt decrease) -- expressed as: (afterBorrowSupply >= beforeBorrowSupply) and (if afterBorrowSupply > beforeBorrowSupply then afterBorrowSupply - beforeBorrowSupply <= (afterDebtSupply >= beforeDebtSupply ? afterDebtSupply - beforeDebtSupply : beforeDebtSupply - afterDebtSupply))
        // We compute diffs carefully to avoid underflow in asserts by using comparisons.

        if (!reverted) {
            // borrow supply did not decrease
            bool borrowNotDecreased = afterBorrowSupply >= beforeBorrowSupply;

            uint256 borrowIncrease = borrowNotDecreased ? afterBorrowSupply - beforeBorrowSupply : 0;
            uint256 debtDiff = afterDebtSupply >= beforeDebtSupply ? afterDebtSupply - beforeDebtSupply : beforeDebtSupply - afterDebtSupply;

            // If there was an increase in borrow supply (which could signal deposit to variable pool), it should be <= debt supply diff
            bool increaseBoundOk = borrowIncrease == 0 || borrowIncrease <= debtDiff;

            assert(borrowNotDecreased && increaseBoundOk);
        } else {
            // If reverted, nothing else guaranteed; assert that supplies unchanged or borrow did not increase beyond debt diff
            // Ensure at least that if reverted, supplies remained equal (no state change) OR borrow didn't increase beyond debt diff
            bool unchanged = (afterBorrowSupply == beforeBorrowSupply) && (afterDebtSupply == beforeDebtSupply);
            uint256 borrowIncreaseIfAny = afterBorrowSupply >= beforeBorrowSupply ? afterBorrowSupply - beforeBorrowSupply : 0;
            uint256 debtDiffIfAny = afterDebtSupply >= beforeDebtSupply ? afterDebtSupply - beforeDebtSupply : 0;
            bool safe = unchanged || borrowIncreaseIfAny <= debtDiffIfAny;
            assert(safe);
        }
    }

    receive() external payable {}
}

