    // We will call deposit to mint collateral tokens. Parameters:
    // token should be the underlyingCollateralToken address (observed via c.data())
    // amount is the deposit amount; to send ETH for WETH path, msg.value must be provided by the caller of run
    function run(address token, uint256 amount) public payable {
        require(true);
        // read data view to obtain underlyingCollateralToken address and view balances
        (uint256 nextDebtId, uint256 nextCreditId) = c.getPositionsCount(); // harmless view to ensure c accessible

        // get data() to discover the configured underlyingCollateralToken and collateralToken
        SizeView.DataView memory dv = c.data();
        address underlyingCollateral = address(dv.underlyingCollateralToken);
        NonTransferrableToken collateralToken = dv.collateralToken;

        // Precondition: only proceed when token equals the protocol's underlyingCollateralToken
        // If not, we expect deposit to revert (since validateDeposit checks token). We'll capture both behaviors.
        bool preIsRightToken = (token == underlyingCollateral);

        // observe recipient balances before (we will deposit to address this contract)
        uint256 beforeCollateralBalance = collateralToken.balanceOf(address(this));

        // Prepare call: deposit(DepositParams)
        // Build calldata for c.deposit
        bytes memory data = abi.encodeWithSelector(
            c.deposit.selector,
            // DepositParams: (address token, uint256 amount, address to)
            // We deposit for ourselves (to = address(this))
            // Note: if token is WETH and msg.value >0 path is taken by c only when token == weth and msg.value==amount
            // We forward msg.value as provided to this function.
            (AddressDepositParams){token: token, amount: amount, to: address(this)}
        );

        // Solidity doesn't allow encoding a struct type defined in another contract here; instead encode as tuple
        bytes memory depositCalldata = abi.encodeWithSelector(
            c.deposit.selector,
            token,
            amount,
            address(this)
        );

        bool reverted = false;
        // We must ensure we have enough balance to send msg.value if used; the caller funded this tx
        // Perform low-level call so we can catch revert without bubbling
        (bool ok, ) = address(c).call{value: msg.value}(depositCalldata);
        if (!ok) {
            reverted = true;
        }

        uint256 afterCollateralBalance = collateralToken.balanceOf(address(this));

        // General rule to assert:
        // - If deposit call reverted, collateral balance must be unchanged
        // - If deposit call succeeded and token == underlyingCollateralToken, afterBalance >= beforeBalance and increased by at least min(amount, after-before)
        // Because protocol mints 1:1 szToken for underlying collateral, after - before should be >= min(amount, after-before)
        // Formally assert: reverted => after == before; !reverted => after >= before && (token==underlyingCollateral implies after - before >= amount)

        // Compute delta carefully to avoid underflow
        uint256 delta = afterCollateralBalance >= beforeCollateralBalance ? afterCollateralBalance - beforeCollateralBalance : 0;

        assert(
            (reverted && afterCollateralBalance == beforeCollateralBalance)
            || (
                !reverted
                && afterCollateralBalance >= beforeCollateralBalance
                && (preIsRightToken ? delta >= amount : true)
            )
        );
    }

    // Minimal helper type-less fallback to accept ETH forwarded to this contract for tests
    receive() external payable {}
}

