contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We deposit then withdraw the same token and assert that positions counters didn't increase
    // and the protocol's visible next ids remain consistent and that withdraw will not transfer more
    // than the depositor had deposited (observed via collateralToken / borrowAToken balances through view getters).

    // The test takes parameters: token address (either underlyingCollateralToken or underlyingBorrowToken), amount, and recipient for withdraw.
    function run(address token, uint256 amount, address to) public payable {
        require(token != address(0));
        // fund this contract if msg.value is intended to be used with WETH deposit path
        // We will allow deposits of either underlyingCollateralToken or underlyingBorrowToken via c.deposit

        // Read positions counts before
        (uint256 beforeDebtCount, uint256 beforeCreditCount) = c.getPositionsCount();

        // Read data view to obtain underlying token addresses to validate token param
        // data().underlyingCollateralToken and data().underlyingBorrowToken are returned as IERC20Metadata in DataView
        // Use try/catch to avoid revert if invalid token address
        // We will attempt to deposit only if token matches one of the two underlying tokens from c.data()

        // Fetch data view
        SizeView.DataView memory dv = c.data();

        bool depositCalled = false;
        // If token is WETH path (collateral) we call deposit with params; otherwise if borrow token, deposit borrow path
        C.DepositParams memory params = C.DepositParams({token: token, amount: amount, to: address(this)});

        // To call c.deposit with possible ETH for WETH route, ensure we have enough balance
        if (token == address(dv.underlyingCollateralToken) || token == address(dv.underlyingBorrowToken)) {
            // attempt deposit; we don't know token approvals in test environment, so wrap in try/catch and record revert
            bool depositReverted = false;
            try c.deposit{value: msg.value}(params) {
                depositReverted = false;
                depositCalled = true;
            } catch {
                depositReverted = true;
                depositCalled = false;
            }

            // Now attempt a withdraw of same token up to `amount` to `to` and capture whether it reverts
            C.WithdrawParams memory wparams = C.WithdrawParams({token: token, amount: amount, to: to});
            bool withdrawReverted = false;
            try c.withdraw{value: 0}(wparams) returns (bytes memory) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }

            // Read positions counts after
            (uint256 afterDebtCount, uint256 afterCreditCount) = c.getPositionsCount();

            // Observables: collateralToken and borrowAToken balances for this contract and for `to` via getUserView
            SizeView.UserView memory beforeView = c.getUserView(address(this));
            SizeView.UserView memory toViewBefore = c.getUserView(to);
            // get balances after operations
            SizeView.UserView memory afterView = c.getUserView(address(this));
            SizeView.UserView memory toViewAfter = c.getUserView(to);

            // Assert general rule:
            // - executing deposit then withdraw (regardless of revert on either) does not change the next positions counters
            //   (i.e., no new debt/credit positions are created by plain deposit/withdraw)
            // - if withdraw succeeded then the recipient's collateral or borrowAToken balance did not increase by more than `amount`
            //   (protocol cannot create tokens out of thin air via withdraw)

            assert(
                afterDebtCount == beforeDebtCount
                && afterCreditCount == beforeCreditCount
                && (
                    // either withdraw reverted (so no transfer), or if successful then `to` balances increased by at most amount
                    withdrawReverted
                        || (
                            // if withdrawing underlyingBorrowToken, borrowAToken.balanceOf(to) should increase <= amount
                            (token == address(dv.underlyingBorrowToken)
                                ? (toViewAfter.borrowATokenBalance - toViewBefore.borrowATokenBalance) <= amount
                                // else collateral token path: collateralToken balance increase <= amount
                                : (toViewAfter.collateralTokenBalance - toViewBefore.collateralTokenBalance) <= amount
                            )
                        )
                )
            );
        } else {
            // If token not recognized, simply assert positions unchanged (we didn't interact)
            (uint256 afterDebtCount2, uint256 afterCreditCount2) = c.getPositionsCount();
            assert(afterDebtCount2 == beforeDebtCount && afterCreditCount2 == beforeCreditCount);
        }
    }

    // receive to accept ETH if test runner funds this contract
    receive() external payable {}
}

