    // We pass an array of bytes to multicall and send optional etherAmount.
    // The test will call c.multicall and then observe public totals to assert CapsLibrary property.
    function run(bytes[] calldata data, uint256 etherAmount) public payable {
        require(address(this).balance >= etherAmount, "insufficient balance for call");

        // snapshot before
        (uint256 borrowBefore, uint256 debtBefore) = c.getPositionsCount();
        // Note: getPositionsCount returns counts, not supplies. We need supplies: use public borrowAToken and debtToken via data() view
        // Retrieve the DataView to access tokens' public totalSupply via the view functions
        // c.data() returns DataView with borrowAToken and debtToken addresses; but DataView returns contract types so we can call totalSupply() on them
        Size.DataView memory dv = c.data();
        uint256 borrowATokenSupplyBefore = dv.borrowAToken.totalSupply();
        uint256 debtTokenSupplyBefore = dv.debtToken.totalSupply();

        bool reverted = false;
        // perform multicall sending etherAmount
        try c.multicall{value: etherAmount}(data) returns (bytes[] memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after snapshot
        Size.DataView memory dv2 = c.data();
        uint256 borrowATokenSupplyAfter = dv2.borrowAToken.totalSupply();
        uint256 debtTokenSupplyAfter = dv2.debtToken.totalSupply();

        // compute increases/decreases safely using comparisons to avoid underflow
        uint256 borrowIncrease = borrowATokenSupplyAfter >= borrowATokenSupplyBefore
            ? borrowATokenSupplyAfter - borrowATokenSupplyBefore
            : 0;
        uint256 debtDecrease = debtTokenSupplyBefore >= debtTokenSupplyAfter
            ? debtTokenSupplyBefore - debtTokenSupplyAfter
            : 0;

        // The invariant enforced by Multicall::multicall (CapsLibrary.validateBorrowATokenIncreaseLteDebtTokenDecrease)
        // must hold whenever borrowATokenSupplyAfter > borrowATokenCap. We cannot read borrowATokenCap directly here,
        // but we can observe that if borrowATokenSupplyAfter > debtTokenSupplyAfter (a weaker observable bound), then
        // either multicall reverted or the borrow increase was compensated by debt decrease. We assert the intended invariant:
        // if the multicall succeeded (not reverted) then either borrowATokenSupplyAfter <= dv2.borrowAToken.totalSupply() (trivial)
        // but more meaningfully: if borrowATokenSupplyAfter > dv2.borrowAToken.totalSupply() it's impossible. To create a general nontrivial rule,
        // we assert: if multicall did not revert then borrowIncrease <= debtDecrease OR borrowATokenSupplyAfter <= dv2.borrowAToken.totalSupply() (tautology).
        // To make it useful: we assert that if multicall succeeded then borrowIncrease <= debtDecrease OR borrowATokenSupplyAfter <= debtTokenSupplyAfter + borrowIncrease;
        // Simplify to the core CapsLibrary condition: if multicall succeeded and borrowATokenSupplyAfter > borrowATokenSupplyBefore and borrowATokenSupplyAfter > dv2.borrowAToken.totalSupply() then borrowIncrease <= debtDecrease.

        // Final assert: when multicall returns (i.e., not reverted) the borrowIncrease is never greater than debtDecrease unless supply is not above cap —
        // since we cannot read cap, we conservatively assert borrowIncrease <= debtDecrease || reverted.
        assert(reverted || borrowIncrease <= debtDecrease);
    }

    receive() external payable {}
}

