        uint256 afterCollateralBalance = afterView.collateralTokenBalance;
        uint256 afterBorrowATokenBalance = afterView.borrowATokenBalance;

        // General rule to assert:
        // For the token path exercised, the protocol-visible balance after deposit+withdraw cannot exceed the balance right after deposit.
        // (i.e., withdraw cannot magically increase the user's protocol balance)
        if (token == collateral) {
            // compare midCollateralBalance and afterCollateralBalance
