contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll simulate depositing collateralToken by calling c.deposit with params.token == underlyingCollateralToken
    // We cannot mint ERC20s here; the checker will provide initial approvals/balances if needed. We only call and observe.
    function run(address token, uint256 amount, address to) public payable {
        require(amount != 0);
        // Read pre-state via public view functions
        ISizeView.DataView memory dv = c.data();
        address underlyingCollateral = address(dv.underlyingCollateralToken);
        // Only proceed if the provided token matches the protocol's collateral token address; otherwise call is expected to revert
        bool willCallMatching = (token == underlyingCollateral);

        // read balances before
        uint256 c_balance_before = IERC20_1(token).balanceOf(address(c));
        uint256 to_collateral_before = dv.collateralToken.balanceOf(to);

        bool reverted;
        try c.deposit{value: msg.value}(DepositParams({token: token, amount: amount, to: to})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 c_balance_after = IERC20_1(token).balanceOf(address(c));
        ISizeView.DataView memory dv_after = c.data();
        uint256 to_collateral_after = dv_after.collateralToken.balanceOf(to);

        // General rule:
        // - If the call reverted, then no guarantees about balances. If it didn't revert and token matched underlyingCollateralToken,
        //   then the recipient's Size collateral token balance must have increased by at least min(amount, change in token balance of C)
        //   and C's token balance must have increased (or stayed same if amount was 0, but we required amount!=0).
        if (!reverted && willCallMatching) {
            // compute how much underlying token moved into C
            uint256 movedIntoC = c_balance_after >= c_balance_before ? c_balance_after - c_balance_before : 0;
            // the recipient's Size collateralToken balance must have increased by at least movedIntoC (since protocol mints 1:1 sz tokens)
            // allow for rounding/truncation so require to_collateral_after >= to_collateral_before and the delta <= movedIntoC
            assert(to_collateral_after >= to_collateral_before && to_collateral_after - to_collateral_before <= movedIntoC);
        } else {
            // If either reverted or token didn't match, assert that either the call reverted or nothing unexpected: recipient collateral didn't increase
            assert(reverted || to_collateral_after == to_collateral_before);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test deposit behavior: token must match protocol's underlyingCollateralToken to succeed.
    // Params: token address, amount to deposit, recipient 'to', and etherValue to send (for WETH flows).
    function run(address token, uint256 amount, address to, uint256 etherValue) public payable {
        require(to != address(0));
        // Ensure we have enough balance to forward ether if caller chooses to send it
        if (etherValue > 0) {
            require(address(this).balance >= etherValue);
        }

        // Observe protocol public data before the call
        // Use the public view c.data() via SizeView interface
        ISizeView.DataView memory dv_before = c.data();
        address underlyingCollateral = address(dv_before.underlyingCollateralToken);

        // read underlying collateral balances before
        uint256 c_underlying_before = IERC20_1(token).balanceOf(address(c));
        // read protocol collateral token (sz token) balance of recipient before
        uint256 to_sz_before = dv_before.collateralToken.balanceOf(to);

        bool reverted;
        // construct params calldata for deposit: DepositParams(token, amount, to)
        bytes memory depositCalldata = abi.encodeWithSignature(
            "deposit((address,uint256,address))",
            token,
            amount,
            to
        );

        // Call deposit; forward etherValue
        try c.deposit{value: etherValue}(DepositParams({token: token, amount: amount, to: to})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after state
        ISizeView.DataView memory dv_after = c.data();
        uint256 c_underlying_after = IERC20_1(token).balanceOf(address(c));
        uint256 to_sz_after = dv_after.collateralToken.balanceOf(to);

        // If the call reverted then we expect no change in observed balances (external calls that revert should not modify state)
        if (reverted) {
            assert(c_underlying_after == c_underlying_before && to_sz_after == to_sz_before);
            return; // reached assert; function ends
        }

        // If the call did not revert and token equals the protocol's underlyingCollateralToken
        // then protocol should have received underlying tokens (increase in c's token balance), and minted sz tokens 1:1
        if (token == underlyingCollateral) {
            // increase in underlying held by protocol
            uint256 moved = c_underlying_after >= c_underlying_before ? c_underlying_after - c_underlying_before : 0;
            // the recipient's sz balance must have increased by at least that moved amount (mint is 1:1)
            // It's acceptable if minted amount equals moved; require at least equality of minted >= moved
            uint256 minted = to_sz_after >= to_sz_before ? to_sz_after - to_sz_before : 0;
            assert(minted >= moved);
        } else {
            // If token doesn't match underlyingCollateral, deposit is expected to revert; but if it didn't, then it must not have minted sz tokens
            // i.e., recipient sz balance should be unchanged
            assert(to_sz_after == to_sz_before);
        }
    }

    // Minimal type shims to allow compilation against existing interfaces
    struct DepositParams { address token; uint256 amount; address to; }
    // Forward receive so contract can hold ETH for etherValue forwarding
    receive() external payable {}
}

