    function run(address token, uint256 amount, bool sendValue) public payable {
        require(amount > 0);

        // Read data view before
        ISize.DataView memory before = c.data();
        uint256 borrowATokenTotalBefore = before.borrowAToken.totalSupply();
        uint256 debtTokenTotalBefore = before.debtToken.totalSupply();
        uint256 cBalanceBefore = address(c).balance;

        // If we will send ETH, ensure this contract has enough balance
        if (sendValue) {
            require(address(this).balance >= amount, "need balance for msg.value");
        }

        // Prepare params struct encoded for call
        // We will call c.deposit with DepositParams: (token, amount, to)
        bytes memory data = abi.encodeWithSignature(
            "deposit((address,uint256,address))",
            token,
            amount,
            address(this)
        );

        bool reverted;
        // perform call with or without value
        (bool ok, ) = address(c).call{value: sendValue ? amount : 0}(data);
        reverted = !ok;

        // Read after state (only via public view functions)
        ISize.DataView memory after = c.data();
        uint256 borrowATokenTotalAfter = after.borrowAToken.totalSupply();
        uint256 debtTokenTotalAfter = after.debtToken.totalSupply();
        uint256 cBalanceAfter = address(c).balance;

