        // If deposit succeeded and token equals the protocol's underlyingBorrowToken, then borrowAToken totalSupply must be >= before
        // If deposit succeeded and msg.value was sent (sendValue==true) then c's balance must increase by amount (WETH deposit path uses msg.value)
        // If deposit reverted, totals and balances must be unchanged.
        assert(
            (
                // successful call path
                !reverted
                    && token == address(before.underlyingBorrowToken)
                    ? borrowATokenTotalAfter >= borrowATokenTotalBefore
                // successful collateral deposit: collateralToken minted but borrowAToken unchanged
                    : (!reverted && token == address(before.underlyingCollateralToken)
                        ? borrowATokenTotalAfter == borrowATokenTotalBefore
                      // successful WETH via msg.value: contract balance increased by amount
                        : (!reverted && sendValue
                            ? cBalanceAfter == cBalanceBefore + amount
                            // other successful cases: no change to c.balance
                            : (!reverted
                                ? cBalanceAfter == cBalanceBefore
                                // reverted: nothing changed
                                : (borrowATokenTotalAfter == borrowATokenTotalBefore
                                    && debtTokenTotalAfter == debtTokenTotalBefore
                                    && cBalanceAfter == cBalanceBefore))
                          )
                      )
            )
        );
    }

    // Allow this contract to receive ETH so tests that require funding can work
    receive() external payable {}
}

