        // Read after-values
        (DataView memory dv2) = c.data();
        uint256 borrowATotalAfter = dv2.borrowAToken.totalSupply();
        uint256 collateralAfter = dv2.collateralToken.balanceOf(to);
        uint256 cBalAfter = address(c).balance;

        // General rule to assert (covers all inputs):
        // - If deposit reverted, none of the observed public supplies/balances increased (they remain equal), and contract balance unchanged.
        // - If deposit succeeded and token equals underlyingBorrowToken, borrowAToken.totalSupply() must be >= before.
        // - If deposit succeeded and token equals underlyingCollateralToken, recipient collateral balance must be >= before and increase by at most amount.

        if (reverted) {
            assert(borrowATotalAfter == borrowATotalBefore && collateralAfter == collateralBefore && cBalAfter == cBalBefore);
        } else {
            // successful call: at least one of the observable supplies/balances must not decrease
            bool borrowOk = (borrowATotalAfter >= borrowATotalBefore);
            bool collOk = (collateralAfter >= collateralBefore && collateralAfter - collateralBefore <= amount);
            // contract Ether balance must be unchanged by deposit (deposit may wrap ETH only when token==weth and msg.value used; but deposit implementation uses msg.value only when token==weth and msg.value==amount; we conservatively allow either unchanged or increased by msg.value)
            bool cbalOk = (cBalAfter == cBalBefore || cBalAfter == cBalBefore + msg.value);

            // Now decide which expectation based on which underlying addresses were provided
            address underlyingBorrow = address(dv.underlyingBorrowToken);
            address underlyingCollateral = address(dv.underlyingCollateralToken);

            if (asBorrowToken) {
                // Expect borrowAToken supply non-decreasing and cbal unchanged or increased by msg.value
                assert(borrowOk && cbalOk);
            } else {
                // Expect collateral token minted to `to` (non-decreasing, not more than amount)
                assert(collOk && cbalOk);
            }
        }
    }

    receive() external payable {}

    // Minimal typed structs to encode calldata for deposit
    struct DepositParams { address token; uint256 amount; address to; }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that calling multicall with arbitrary calldata either reverts or preserves the invariant
    // validated by Multicall: after executing delegatecalls, CapsLibrary.validateBorrowATokenIncreaseLteDebtTokenDecrease
    // ensures that if borrowATokenSupply increased above cap then increase <= debt decrease. We assert a general property
    // observable via public surface: if multicall does NOT revert, then borrowAToken.totalSupply() >= borrowBefore implies
    // debtToken.totalSupply() <= debtBefore + (borrowAToken.totalSupply() - borrowBefore). This rearranges to
    // borrowIncrease <= debtDecrease + epsilon; equivalently debtBefore + borrowIncrease >= debtAfter.

    // The function accepts an array of bytes for multicall and an amount of wei to forward with the call.
    function run(bytes[] calldata inputs, uint256 value) public payable {
        // ensure this contract holds enough Ether to forward if requested
        require(address(this).balance >= value);

        // Observe before-values via public view functions
        (uint256 borrowCountBefore, uint256 creditCountBefore) = c.getPositionsCount(); // innocuous views
        // Read borrowAToken and debtToken total supplies via data() view
        ISize.DataView memory dvBefore = c.data();
        uint256 borrowATotalBefore = dvBefore.borrowAToken.totalSupply();
        uint256 debtTokenTotalBefore = dvBefore.debtToken.totalSupply();
        uint256 cBalBefore = address(c).balance;

        bool reverted = false;
        bytes[] memory results;
        // perform multicall on c forwarding `value` wei
        try c.multicall{value: value}(inputs) returns (bytes[] memory res) {
            results = res;
        } catch {
            reverted = true;
        }

        // Observe after-values
        ISize.DataView memory dvAfter = c.data();
        uint256 borrowATotalAfter = dvAfter.borrowAToken.totalSupply();
        uint256 debtTokenTotalAfter = dvAfter.debtToken.totalSupply();
        uint256 cBalAfter = address(c).balance;

        // General rule (single assert):
        // If multicall reverted, then nothing is required about c's totals here (we only assert that some revert occurred or the invariant holds).
        // If multicall succeeded, then the following observable invariant must hold:
        // debtTokenTotalBefore + (borrowATotalAfter - borrowATotalBefore) >= debtTokenTotalAfter
        // (i.e., any increase in borrow aToken supply must be matched by at least that much decrease in debt token supply,
        // as enforced by validateBorrowATokenIncreaseLteDebtTokenDecrease after multicall)
        // Also, the contract balance change must equal the forwarded value handled by the multicall (multicall should not spontaneously create/destroy ETH): cBalAfter == cBalBefore + value || cBalAfter == cBalBefore

        assert(
            reverted
            || (
                // borrow increase (possibly zero) is accounted for by debt decrease
                debtTokenTotalBefore + (borrowATotalAfter - borrowATotalBefore) >= debtTokenTotalAfter
                // and contract balance did not decrease below expected (conservative: either unchanged or increased by forwarded value)
                && (cBalAfter == cBalBefore || cBalAfter == cBalBefore + value)
            )
        );
    }

    // allow receiving ETH so the test contract can forward value
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single entry that forwards ETH and a batch of calls to multicall on C.
    // Observes borrowAToken.totalSupply() and debtToken.totalSupply() via the public data() view before and after.
    function run(bytes[] calldata inputs, uint256 value) public payable {
        // allow forwarding Ether: require this contract has enough balance
        require(address(this).balance >= value);

        // Read before-state via public view: get DataView from c.data()
        ISize.DataView memory dvBefore = c.data();
        uint256 borrowATotalBefore = dvBefore.borrowAToken.totalSupply();
        uint256 debtTokenTotalBefore = dvBefore.debtToken.totalSupply();
        uint256 cBalBefore = address(c).balance;

        bool reverted = false;
        bytes[] memory results;
        // call multicall (top-level state-changing call) forwarding `value` wei
        try c.multicall{value: value}(inputs) returns (bytes[] memory res) {
            results = res;
        } catch {
            reverted = true;
        }

        // Read after-state via public view
        ISize.DataView memory dvAfter = c.data();
        uint256 borrowATotalAfter = dvAfter.borrowAToken.totalSupply();
        uint256 debtTokenTotalAfter = dvAfter.debtToken.totalSupply();
        uint256 cBalAfter = address(c).balance;

        // Assert the general invariant enforced by Multicall/CapsLibrary when multicall does not revert:
        // any increase in borrowAToken total supply must be accounted for by at least that much decrease in debtToken total supply.
        // Formally: if not reverted then debtBefore + (borrowAfter - borrowBefore) >= debtAfter
        assert(
            reverted
            || (debtTokenTotalBefore + (borrowATotalAfter - borrowATotalBefore) >= debtTokenTotalAfter)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will invoke deposit to deposit into underlyingBorrowToken into the variable pool.
    // Parameters:
    // - to: recipient address to credit the Size borrow token
    // - amount: amount of tokens to deposit
    // - token: the address of the underlyingBorrowToken (we take it as an address param so checker supplies some token address or zero)
    // The test checks that either the call reverts, or borrowAToken.totalSupply() is not decreased (monotonic) and if increased, the increase is reflected in c.data().borrowAToken.totalSupply().
    function run(address token, address to, uint256 amount, uint256 valueForMsg) public payable {
        // allow forwarding Ether only if this contract has that balance
        require(address(this).balance >= valueForMsg);

        // Read before-state via public view
        ISize.DataView memory dvBefore = c.data();
        uint256 borrowATotalBefore = dvBefore.borrowAToken.totalSupply();

        bool reverted = false;
        // We must call deposit as a top-level state-changing call. Forward Ether if requested.
        try c.deposit{value: valueForMsg}(ISize.DepositParams({token: token, amount: amount, to: to})) {
            // success
        } catch {
            reverted = true;
        }

        // Read after-state via public view
        ISize.DataView memory dvAfter = c.data();
        uint256 borrowATotalAfter = dvAfter.borrowAToken.totalSupply();

        // General rule:
        // If the call reverted, nothing to assert about totals except that we allow revert case.
        // Otherwise (not reverted): borrowAToken.totalSupply() must be >= before (monotonic non-decrease on successful deposit of borrow token)
        // and the change is observable via the public getter: borrowATotalAfter >= borrowATotalBefore
        assert(reverted || (borrowATotalAfter >= borrowATotalBefore));
    }

    receive() external payable {}
}
